actions.script:
import java.util.regex.Pattern

def pathCache = ec.cache.getCache('growerp.security.restDomain')
def cached = pathCache.get(artifactName)
if (cached != null) {
    artifactGroupId = ('_NONE_' == cached) ? null : cached
    return
}

def patternCache = ec.cache.getCache('growerp.security.restPatterns')
List patterns = (List) patternCache.get('all')
if (patterns == null) {
    patterns = []
    ec.entity.find('moqui.security.ArtifactGroupMember')
        .condition('artifactTypeEnumId', 'AT_REST_PATH')
        .condition('nameIsPattern', 'Y').list().each { member ->
            String groupId = member.artifactGroupId?.toString()
            // the domains only; GROWERP_REST_GUARDED is the guard itself and
            // GROWERP_API is the legacy catch all
            if (groupId != null && groupId.startsWith('GROWERP_') &&
                    groupId != 'GROWERP_REST_GUARDED' && groupId != 'GROWERP_API' &&
                    groupId != 'GROWERP_API_SCREEN') {
                patterns.add([groupId: groupId,
                              pattern: Pattern.compile(member.artifactName.toString())])
            }
        }
    patternCache.put('all', patterns)
}

def match = patterns.find { it.pattern.matcher(artifactName).matches() }
pathCache.put(artifactName, match ? match.groupId : '_NONE_')
artifactGroupId = match?.groupId

import groovy.json.JsonSlurper

def cache = ec.cache.getCache('growerp.security.ownerDomain')
String key = ownerPartyId + '|' + userGroupId
Map hit = (Map) cache.get(key)
if (hit != null) { domainAccess = hit; return }

def slurper = new JsonSlurper()
def parseGroups = { jsonStr ->
    if (!jsonStr) return null
    try { return slurper.parseText(jsonStr.toString()) } catch (e) { return null }
}
// Same default as get#MenuConfiguration: no list means the internal groups,
// never the outside group.
def allows = { groups ->
    if (!groups) return userGroupId != 'GROWERP_M_OTHER'
    return groups.contains(userGroupId)
}
// Write follows view unless a screen names its writers. Without this every
// seed item, which carries no updateGroupsJson, would be read only and the
// whole application would 403 on save.
def allowsWrite = { writeGroups ->
    if (writeGroups == null) return userGroupId != 'GROWERP_M_OTHER'
    return writeGroups.contains(userGroupId)
}

// The apps this organization actually has: the ones it customised, plus the
// one it registered for. A REST call carries no appId, so without this every
// seed menu would count and a hotel tenant would inherit manufacturing.
Set appIds = new HashSet()
ec.entity.find('growerp.menu.MenuConfiguration')
    .condition('ownerPartyId', ownerPartyId).condition('userId', null)
    .list().each { appIds.add(it.appId?.toString()) }
def tenantSetup = ec.entity.find('growerp.general.TenantSetup')
    .condition('ownerPartyId', ownerPartyId).one()
if (tenantSetup?.applicationId) {
    String appId = tenantSetup.applicationId.toString()
    if (appId.startsWith('App')) appId = appId.substring(3)
    appIds.add(appId.toLowerCase())
}
appIds.remove(null)

Map widgetDomains = [:]
ec.entity.find('growerp.menu.WidgetDomain').list().each {
    widgetDomains[it.widgetName?.toString()] = it.artifactGroupId?.toString()
}

Map access = [:]
appIds.each { appId ->
    // the organization's own configuration for this app, else the seed
    def configs = ec.entity.find('growerp.menu.MenuConfiguration')
        .condition('appId', appId).condition('userId', null)
        .condition('ownerPartyId', ownerPartyId).list()
    if (!configs) {
        configs = ec.entity.find('growerp.menu.MenuConfiguration')
            .condition('appId', appId).condition('userId', null)
            .condition('ownerPartyId', null).list()
    }
    if (!configs) return

    def items = ec.entity.find('growerp.menu.MenuItem')
        .condition('menuConfigurationId', configs[0].menuConfigurationId).list()
    Map byId = [:]
    items.each { byId[it.menuItemId?.toString()] = it }

    // a child is only reachable when its parent is
    def visible
    visible = { item ->
        if (!allows(parseGroups(item.userGroupsJson))) return false
        def parentId = item.parentMenuItemId?.toString()
        if (!parentId) return true
        def parent = byId[parentId]
        return parent == null ? true : visible(parent)
    }

    items.each { item ->
        if (item.isActive == 'N') return
        if (!visible(item)) return
        String domain = item.artifactGroupId?.toString()
        if (!domain) domain = widgetDomains[item.widgetName?.toString()]
        if (!domain) return
        if (allowsWrite(parseGroups(item.updateGroupsJson))) access[domain] = 'WRITE'
        else if (access[domain] == null) access[domain] = 'SEE'
    }
}

cache.put(key, access)
domainAccess = access

def cache = ec.cache.getCache('growerp.security.ownerDomain')
if (ownerPartyId) {
    ['GROWERP_M_SYSTEM', 'GROWERP_M_ADMIN', 'GROWERP_M_EMPLOYEE',
     'GROWERP_M_OTHER'].each { cache.remove(ownerPartyId + '|' + it) }
} else {
    cache.clear()
}
